// Derived identities (#73 D1, D2; #78): the v1 derivation matches the frozen
// test vectors (generated by Node's own HKDF in scripts/derive-vectors.mjs),
// and on shared sign-in the user's identity is identity 0, never the login key.
import { test, expect } from "@playwright/test";
import { readFileSync } from "node:fs";
import { getPublicKey } from "nostr-tools/pure";
import {
  canonicalOrigin, deriveBackupKey, deriveConfigKey, deriveCounterKey, deriveIdentity,
  deriveMarkerAddress, deriveMarkerKey, deriveRoot, deriveSettingsKey, deriveStoreKey,
} from "../bunker/src/lib/derive.ts";
import { sharedIdentity } from "../bunker/src/lib/identity.ts";

const vectors = JSON.parse(readFileSync(new URL("../bunker/src/lib/derive.vectors.json", import.meta.url), "utf8"));
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const bytes = (h: string) => new Uint8Array(Buffer.from(h, "hex"));

test("derivation matches the frozen vectors", async () => {
  for (const v of vectors.vectors) {
    const root = await deriveRoot(bytes(v.globalLoginKey));
    expect(hex(root)).toBe(v.root.secret);
    for (const id of v.identities) {
      const k = await deriveIdentity(root, id.index);
      expect(hex(k)).toBe(id.secret);
      expect(getPublicKey(k)).toBe(id.pubkey);
    }
    for (const s of v.sites) {
      expect(canonicalOrigin(s.input)).toBe(s.canonical);
      expect(hex(await deriveMarkerKey(root, s.input))).toBe(s.markerKey.secret);
      expect(hex(await deriveStoreKey(root, s.input))).toBe(s.storeKey);
      expect(await deriveMarkerAddress(bytes(s.markerAddress.siteLoginKey), s.input)).toBe(s.markerAddress.d);
    }
    expect(hex(await deriveCounterKey(root))).toBe(v.counterKey.secret);
    expect(hex(await deriveConfigKey(root))).toBe(v.configKey.secret);
    expect(hex(await deriveBackupKey(root))).toBe(v.backupKey);
    expect(hex(await deriveSettingsKey(bytes(v.settingsKeyFromM.m)))).toBe(v.settingsKeyFromM.key);
  }
});

test("non-web origins are refused", () => {
  for (const bad of ["file:///etc/passwd", "data:text/html,x", "not a url", "javascript:alert(1)"])
    expect(() => canonicalOrigin(bad)).toThrow();
});

test("shared sign-in: the identity is identity 0, not the login key, and the login key is wiped", async () => {
  const v = vectors.vectors[0];
  const loginKey = bytes(v.globalLoginKey);
  const login = {
    privateKeyBytes: loginKey,
    publicKeyHex: getPublicKey(bytes(v.globalLoginKey)),
    nsecStr: "nsec-of-login",
    npubStr: "npub-of-login",
  };
  const id = await sharedIdentity(login, 0);
  expect(id.publicKeyHex).toBe(v.identities[0].pubkey);
  expect(id.publicKeyHex).not.toBe(login.publicKeyHex);
  expect(hex(id.privateKeyBytes)).toBe(v.identities[0].secret);
  expect(id.npubStr.startsWith("npub1")).toBe(true);
  expect(id.nsecStr.startsWith("nsec1")).toBe(true);
  expect(loginKey.every((b) => b === 0)).toBe(true);
});
